#pragma once
// Palette entries for the audio-control nodes. NOT standalone: GraphNodeFamilies.gen.inc (generated by
// cmake/GraphNodeFamilies.cmake) includes it from GraphNodeDefs.hpp inside namespace aver::editor::detail, after
// pin()/attr() are defined, and calls appendAudioControlNodeDefs(t).
//
// MIRRORS scripting/csharp/Aver.Graph/GraphAudioControlNodeTable.cs pin for pin
// (docs/plans/wave9/VISUAL_SCRIPTING_CSHARP_SYNC.md section 2.2). Voice handles are the voice pin of AN_PlayStream,
// AN_PlayStreamAt and AN_PlayMusic. Buses: 0 Sfx, 1 Music, 2 Voice, 3 Ui.

inline void appendAudioControlNodeDefs(std::vector<GraphNodeDesc>& t) {
    t.push_back({"AN_SetMasterVolume", "Set Master Volume", "Audio", {
        pin("exec", "exec", false), pin("volume", "float", false, "1"), pin("then", "exec", true), pin("success", "bool", true)}});
    t.push_back({"AN_GetMasterVolume", "Get Master Volume", "Audio", {
        pin("volume", "float", true)}});
    t.push_back({"AN_GetBusVolume", "Get Bus Volume", "Audio", {
        pin("bus", "int", false), pin("volume", "float", true)}});
    t.push_back({"AN_StopAllSounds", "Stop All Sounds", "Audio", {
        pin("exec", "exec", false), pin("then", "exec", true), pin("success", "bool", true)}});
    t.push_back({"AN_SetVoiceVolume", "Set Voice Volume", "Audio", {
        pin("exec", "exec", false), pin("voice", "int", false), pin("volume", "float", false),
        pin("then", "exec", true), pin("success", "bool", true)}});
    t.push_back({"AN_SetVoicePitch", "Set Voice Pitch", "Audio", {
        pin("exec", "exec", false), pin("voice", "int", false), pin("pitch", "float", false, "1"),
        pin("then", "exec", true), pin("success", "bool", true)}});
    t.push_back({"AN_SetVoicePosition", "Set Voice Position", "Audio", {
        pin("exec", "exec", false), pin("voice", "int", false), pin("x", "float", false), pin("y", "float", false), pin("z", "float", false),
        pin("then", "exec", true), pin("success", "bool", true)}});
    t.push_back({"AN_IsVoicePlaying", "Is Voice Playing", "Audio", {
        pin("voice", "int", false), pin("playing", "bool", true)}});
    t.push_back({"AN_StopVoice", "Stop Voice", "Audio", {
        pin("exec", "exec", false), pin("voice", "int", false), pin("then", "exec", true), pin("success", "bool", true)}});
    t.push_back({"AN_SetOcclusionCurve", "Set Occlusion Curve", "Audio", {
        pin("exec", "exec", false), pin("minCutoffHz", "float", false, "800"), pin("minVolume", "float", false, "0.25"),
        pin("then", "exec", true), pin("success", "bool", true)}});
    t.push_back({"AN_GetAudioStats", "Get Audio Stats", "Audio", {
        pin("activeVoices", "int", true), pin("activeStreams", "int", true), pin("underruns", "int", true)}});
}
